from __future__ import annotations

import base64
import json
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class DecryptPayloadResult:
    plaintext: bytes
    key_id: Optional[str] = None
    encryption_algorithm: Optional[str] = None
    request_id: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "plaintext": base64.b64encode(self.plaintext).decode("utf-8"),
            "key_id": self.key_id,
            "encryption_algorithm": self.encryption_algorithm,
            "request_id": self.request_id,
        }


def _decode_ciphertext(ciphertext: str) -> bytes:
    try:
        return base64.b64decode(ciphertext, validate=True)
    except Exception:
        return ciphertext.encode("utf-8")


def decrypt_payload(ciphertext: str, key_id: Optional[str] = None, encryption_context: Optional[Dict[str, str]] = None) -> DecryptPayloadResult:
    kms = boto3.client("kms", region_name=os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))
    params: Dict[str, Any] = {"CiphertextBlob": _decode_ciphertext(ciphertext)}
    if key_id:
        params["KeyId"] = key_id
    if encryption_context:
        params["EncryptionContext"] = encryption_context

    try:
        response = kms.decrypt(**params)
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"AWS KMS decryption failed: {exc}") from exc

    plaintext = response["Plaintext"]
    return DecryptPayloadResult(
        plaintext=plaintext,
        key_id=response.get("KeyId"),
        encryption_algorithm=response.get("EncryptionAlgorithm"),
        request_id=response.get("ResponseMetadata", {}).get("RequestId"),
    )


def main() -> None:
    import argparse

    parser = argparse.ArgumentParser(description="Decrypt a ciphertext payload with AWS KMS")
    parser.add_argument("ciphertext", help="Ciphertext as base64 or raw text")
    parser.add_argument("--key-id", dest="key_id")
    parser.add_argument("--encryption-context", dest="encryption_context", help="JSON object")
    args = parser.parse_args()

    encryption_context = json.loads(args.encryption_context) if args.encryption_context else None
    result = decrypt_payload(args.ciphertext, key_id=args.key_id, encryption_context=encryption_context)
    print(result.to_dict())


if __name__ == "__main__":
    main()
